mutations.find:
if (s.has(value)) {
  throw new NotCrossable("opaque", `${path} closes a cycle: the value contains itself, and a cycle has no canonical form`);
}
s.add(value);

for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
  assertCrossable(v, `${path}.${k}`, s);
}
s.delete(value);
return;

mutations.replace:
for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
  assertCrossable(v, `${path}.${k}`, s);
}
return;
